// Generated from a 512-square browser canvas with four colored quadrants.
const lossy = ''
const lossless = ''
const alpha = ''
export function avatarWebp(kind: 'lossy' | 'lossless' | 'alpha' = 'lossy'): Uint8Array {
  const value = kind === 'lossless' ? lossless : kind === 'alpha' ? alpha : lossy
  return Uint8Array.from(atob(value), char => char.charCodeAt(0))
}
export function riff(...chunks: Array<[string, Uint8Array]>): Uint8Array {
  const bytes = new Uint8Array(12 + chunks.reduce((sum, [, data]) => sum + 8 + data.length + (data.length % 2), 0))
  bytes.set(new TextEncoder().encode('RIFF'), 0); bytes.set(new TextEncoder().encode('WEBP'), 8)
  const view = new DataView(bytes.buffer); view.setUint32(4, bytes.length - 8, true)
  let offset = 12
  for (const [tag, data] of chunks) {
    bytes.set(new TextEncoder().encode(tag), offset); view.setUint32(offset + 4, data.length, true)
    bytes.set(data, offset + 8); offset += 8 + data.length + (data.length % 2)
  }
  return bytes
}
